window.__finlexDocLoaded(207,{"id":207,"articles":[{"id":5315,"no":"第一条","heading":"","text":"为了规范注册会计师对财务信息执行商定程序业务，明确执业责任，制定本准则。","seq":0},{"id":5316,"no":"第二条","heading":"","text":"对财务信息执行商定程序的目标，是注册会计师对特定财务数据、单一财务报表或整套财务报表等财务信息执行与特定主体商定的具有审计性质的程序，并就执行的商定程序及其结果出具报告。本准则所称特定主体，是指委托人和业务约定书中指明的报告致送对象。","seq":1},{"id":5317,"no":"第三条","heading":"","text":"注册会计师执行商定程序业务，仅报告执行的商定程序及其结果，并不提出鉴证结论。报告使用者自行对注册会计师执行的商定程序及其结果作出评价，并根据注册会计师的工作得出自己的结论。","seq":2},{"id":5318,"no":"第四条","heading":"","text":"商定程序业务报告仅限于参与协商确定程序的特定主体使用，以避免不了解商定程序的人对报告产生误解。","seq":3},{"id":5319,"no":"第五条","heading":"","text":"注册会计师执行商定程序业务，应当遵守相关职业道德规范，恪守客观、公正的原则，保持专业胜任能力和应有的关注，并对执业过程中获知的信息保密。","seq":4},{"id":5320,"no":"第六条","heading":"","text":"本准则不对商定程序业务提出独立性要求；但如果业务约定书或委托目的对注册会计师的独立性提出要求，注册会计师应当从其规定。如果注册会计师不具有独立性，应当在商定程序业务报告中说明这一事实。","seq":5},{"id":5321,"no":"第七条","heading":"","text":"注册会计师应当按照本准则的规定和业务约定书的要求执行商定程序业务。 ## 第二章 业务约定书","seq":6},{"id":5322,"no":"第八条","heading":"","text":"注册会计师应当与特定主体进行沟通，确保其已经清楚理解拟执行的商定程序和业务约定条款。注册会计师应当就下列事项与特定主体沟通，并达成一致意见： （一）业务性质，包括说明执行的商定程序并不构成审计或审阅，不提出鉴证结论； **（二）委托目的；** **（三）拟执行商定程序的财务信息；** **（四）拟执行的具体程序的性质、时间和范围；** **（五）预期的报告样本；** **（六）报告分发和使用的限制。**","seq":7},{"id":5323,"no":"第九条","heading":"","text":"如果无法与所有的报告致送对象直接讨论拟执行的商定程序，注册会计师应当考虑采取下列措施： **（一）与报告致送对象的代表讨论拟执行的商定程序；** **（二）查阅来自报告致送对象的相关信函和文件；** **（三）向报告致送对象提交报告样本。**","seq":8},{"id":5324,"no":"第十条","heading":"","text":"如果接受委托，注册会计师应当与委托人就双方达成一致的事项签订业务约定书，以避免双方对商定程序业务的理解产生分歧。 ## 第三章 计划、程序与记录","seq":9},{"id":5325,"no":"第十一条","heading":"","text":"注册会计师应当合理制定工作计划，以有效执行商定程序业务。","seq":10},{"id":5326,"no":"第十二条","heading":"","text":"注册会计师应当执行商定的程序，并将获取的证据作为出具报告的基础。","seq":11},{"id":5327,"no":"第十三条","heading":"","text":"执行商定程序业务运用的程序通常包括： **（一）询问和分析；** **（二）重新计算、比较和其他核对方法；** **（三）观察；** **（四）检查；** **（五）函证。**","seq":12},{"id":5328,"no":"第十四条","heading":"","text":"注册会计师应当记录支持商定程序业务报告的重大事项，并记录按照本准则的规定和业务约定书的要求执行商定程序的证据。 ## 第四章 报告","seq":13},{"id":5329,"no":"第十五条","heading":"","text":"商定程序业务报告应当详细说明业务的目的和商定的程序，以便使用者了解所执行工作的性质和范围。","seq":14},{"id":5330,"no":"第十六条","heading":"","text":"商定程序业务报告应当包括下列内容： **（一）标题；** **（二）收件人；** **（三）说明执行商定程序的财务信息；** **（四）说明执行的商定程序是与特定主体协商确定的；** （五）说明已按照本准则的规定和业务约定书的要求执行了商定程序； **（六）当注册会计师不具有独立性时，说明这一事实；** **（七）说明执行商定程序的目的；** **（八）列出所执行的具体程序；** （九）说明执行商定程序的结果，包括详细说明发现的错误和例外事项； （十）说明所执行的商定程序并不构成审计或审阅，注册会计师不提出鉴证结论； （十一）说明如果执行商定程序以外的程序，或执行审计或审阅，注册会计师可能得出其他应报告的结果； **（十二）说明报告仅限于特定主体使用；** （十三）在适用的情况下，说明报告仅与执行商定程序的特定财务数据有关，不得扩展到财务报表整体； **（十四）注册会计师的签名和盖章；** **（十五）会计师事务所的名称、地址及盖章；** **（十六）报告日期。** ## 第五章 附则","seq":15},{"id":5331,"no":"第十七条","heading":"","text":"如果注册会计师具备专业胜任能力，且存在合理的判断标准，可参照本准则对非财务信息执行商定程序业务。","seq":16},{"id":5332,"no":"第十八条","heading":"","text":"本准则自2007年1月1日起施行。","seq":17}]});
